# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def decode(raw: bytes) -> str:
    return raw.decode("latin-1", errors="replace").strip()


def send_and_recv(sock: socket.socket, data: bytes, timeout: float,
                  expects_ack_menu_json: bool, verify: bool, dry_run: bool,
                  label: str) -> bool:
    text = decode(data)
    prefix = text[:2] if len(text) >= 2 else text

    if dry_run:
        print(f"  [DRY] {label:>4s} {text[:100]}")
        return True

    sock.send(data)
    print(f"  >>> {label:>4s} {text[:100]}")

    if not verify:
        return True

    sock.settimeout(timeout)
    try:
        resp, _ = sock.recvfrom(65535)
        resp_str = decode(resp)
        print(f"  <<< {resp_str[:100]}")

        if expects_ack_menu_json:
            # Extract jsonId from the sent payload to verify ACK
            try:
                payload_json = text[2:]   # strip 2-char command prefix
                jid = json.loads(payload_json).get("jsonId", "?")
                ok = f"ACK MENU_JSON {jid}" in resp_str
            except Exception:
                ok = "ACK" in resp_str
        else:
            ok = "ACK" in resp_str or len(resp_str) > 0

        if not ok:
            print(f"  [WARN] unexpected response: {resp_str[:80]}")
        return ok

    except socket.timeout:
        print(f"  [WARN] no response (timeout {timeout}s)")
        return False


# ---------------------------------------------------------------------------
# Main push routine
# ---------------------------------------------------------------------------

def push(device_ip: str, port: int, timeout: float, verify: bool,
         dry_run: bool) -> bool:
    import uuid as _uuid

    smid = _uuid.uuid4().hex
    print(f"\nAxon C1 pcap replay push")
    print(f"  Target : {device_ip}:{port}")
    print(f"  SMID   : {smid}")
    print(f"  Timeout: {timeout}s  verify={verify}  dry_run={dry_run}\n")

    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(timeout)
    if not dry_run:
        sock.connect((device_ip, port))

    failures = 0

    for idx, (expects_json_ack, raw) in enumerate(PACKETS):
        # Slot 28 (0-indexed) is the SMID placeholder -- fill it in now
        if raw is None:
            smid_cmd = f"SMID {smid}\r"
            raw = list(smid_cmd.encode("latin-1"))

        data = bytes(raw)
        label = data[:2].decode("latin-1", errors="replace")
        ok = send_and_recv(sock, data, timeout, expects_json_ack,
                           verify, dry_run, label)
        if not ok:
            failures += 1

        # Small inter-packet gap so device doesn't drop packets
        if not dry_run:
            time.sleep(0.02)

    sock.close()

    # Wait for batch result (device sends it ~5s after SF)
    if not dry_run and verify:
        print("\nWaiting for batch result from device (up to 8s)...")
        listener = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        listener.bind(("", port))
        listener.settimeout(8)
        try:
            while True:
                data, addr = listener.recvfrom(65535)
                text = decode(data)
                if '"json_ids"' in text or '"result_ids"' in text:
                    print(f"  Batch result from {addr[0]}: {text[:200]}")
                    try:
                        obj = json.loads(text)
                        bad = [(j, r) for j, r in
                               zip(obj["json_ids"], obj["result_ids"]) if r != 0]
                        if bad:
                            print(f"  {len(bad)} FAILED packet(s): {bad}")
                            failures += len(bad)
                        else:
                            print(f"  All {len(obj['json_ids'])} packets accepted OK")
                    except Exception:
                        pass
                    break
        except socket.timeout:
            print("  (no batch result received -- device may already be committed)")
        finally:
            listener.close()

    print(f"\n{'DONE' if failures == 0 else 'DONE WITH WARNINGS'}  "
          f"({failures} failure(s))\n")
    return failures == 0


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main():
    parser = argparse.ArgumentParser(
        description="Replay CAP2_ALL_KINDS_OF_STUFF.pcapng push sequence to an Axon C1.",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=__doc__,
    )
    parser.add_argument("device_ip",
                        help="IP address of the Axon C1 (e.g. 169.254.2.157)")
    parser.add_argument("--port", type=int, default=CMD_PORT,
                        help=f"UDP command port (default: {CMD_PORT})")
    parser.add_argument("--timeout", type=float, default=2.0,
                        help="Per-packet ACK wait in seconds (default: 2.0)")
    parser.add_argument("--dry-run", action="store_true",
                        help="Print packets without sending")
    parser.add_argument("--no-verify", action="store_true",
                        help="Send without waiting for ACKs")
    args = parser.parse_args()

    ok = push(
        device_ip=args.device_ip,
        port=args.port,
        timeout=args.timeout,
        verify=not args.no_verify,
        dry_run=args.dry_run,
    )
    sys.exit(0 if ok else 1)


if __name__ == "__main__":
    main()